// Базовое событие нажатия клавиши
export interface RawKeyEvent {
  code: string;
  key: string;
  type: 'keydown' | 'keyup';
  timestamp: number;
}

// Извлеченные признаки (Feature Vector)
export interface KeystrokeFeatures {
  totalDuration: number;
  dwellTimes: Record<string, number>; // Время удержания для каждой клавиши (по коду)
  flightTimes: Record<string, number>; // Время полета между парами клавиш (диграфы)
}

// Шаблон пользователя (обученная модель)
export interface UserTemplate {
  phrase: string; // Фраза, на которой обучались
  sampleCount: number;
  means: {
    dwell: Record<string, number>;
    flight: Record<string, number>;
  };
  deviations: {
    dwell: Record<string, number>;
    flight: Record<string, number>;
  };
  threshold: number; // Порог принятия решения
}

// Пользователь системы
export interface User {
  id: string;
  username: string;
  template: UserTemplate | null;
  createdAt: number;
}

// Результат попытки аутентификации
export interface AuthResult {
  success: boolean;
  score: number; // Вычисленное расстояние (чем меньше, тем лучше)
  threshold: number;
  details: string;
  timestamp: number;
}

import { RawKeyEvent, KeystrokeFeatures, UserTemplate } from '../types';

// Преобразование "сырых" событий клавиатуры в вектор признаков
export const extractFeatures = (events: RawKeyEvent[]): KeystrokeFeatures => {
  const dwellTimes: Record<string, number> = {};
  const flightTimes: Record<string, number> = {};

  // Сортировка по времени
  const sortedEvents = [...events].sort((a, b) => a.timestamp - b.timestamp);

  // Временные карты для поиска пар нажатие-отпускание
  const downMap: Record<string, number> = {};

  let previousUpTimestamp: number | null = null;
  let previousKey: string | null = null;

  sortedEvents.forEach((event) => {
    // Уникальный идентификатор нажатия для обработки повторяющихся символов
    // В упрощенной модели ВКР используем event.code + index (или просто логику стека, но здесь упростим до кода)
    // Для простоты предполагаем, что пользователь не нажимает одну клавишу дважды одновременно

    if (event.type === 'keydown') {
      downMap[event.code] = event.timestamp;

      // Расчет Flight Time (latency): от отпускания предыдущей до нажатия текущей
      // Либо от нажатия предыдущей до нажатия текущей (Digraph latency). 
      // Используем P-P (Press-to-Press) как более устойчивую метрику.
      if (previousKey && previousUpTimestamp !== null) {
          // P-P метрика часто надежнее. Но классическая flight - это Release-to-Press.
          // Реализуем Release-to-Press (время полета руки).
          const flight = event.timestamp - previousUpTimestamp;
          const digraph = `${previousKey}->${event.code}`;
          flightTimes[digraph] = flight;
      }
    } else if (event.type === 'keyup') {
      const downTime = downMap[event.code];
      if (downTime !== undefined) {
        const dwell = event.timestamp - downTime;
        // Если клавиша нажималась несколько раз, берем среднее или последнее.
        // Для фразы обычно каждая буква уникальна или позиционна. 
        // Чтобы упростить, запишем dwell с ключом event.code.
        // *Примечание для ВКР: в продакшене нужен позиционный индекс.*
        dwellTimes[event.code] = dwell;

        previousUpTimestamp = event.timestamp;
        previousKey = event.code;
      }
    }
  });

  const startTime = sortedEvents[0]?.timestamp || 0;
  const endTime = sortedEvents[sortedEvents.length - 1]?.timestamp || 0;

  return {
    totalDuration: endTime - startTime,
    dwellTimes,
    flightTimes,
  };
};

// Создание шаблона из нескольких попыток ввода (Training)
export const createTemplate = (samples: KeystrokeFeatures[], phrase: string): UserTemplate => {
  const count = samples.length;
  if (count === 0) throw new Error("No samples provided");

  // 1. Сбор всех ключей
  const allDwellKeys = new Set<string>();
  const allFlightKeys = new Set<string>();

  samples.forEach(s => {
    Object.keys(s.dwellTimes).forEach(k => allDwellKeys.add(k));
    Object.keys(s.flightTimes).forEach(k => allFlightKeys.add(k));
  });

  // 2. Расчет средних (Mean)
  const means: UserTemplate['means'] = { dwell: {}, flight: {} };

  allDwellKeys.forEach(key => {
    const sum = samples.reduce((acc, s) => acc + (s.dwellTimes[key] || 0), 0);
    means.dwell[key] = sum / count;
  });

  allFlightKeys.forEach(key => {
    const sum = samples.reduce((acc, s) => acc + (s.flightTimes[key] || 0), 0);
    means.flight[key] = sum / count;
  });

  // 3. Расчет стандартных отклонений (Std Dev)
  const deviations: UserTemplate['deviations'] = { dwell: {}, flight: {} };

  allDwellKeys.forEach(key => {
    const mean = means.dwell[key];
    const variance = samples.reduce((acc, s) => acc + Math.pow((s.dwellTimes[key] || mean) - mean, 2), 0) / count;
    // Добавляем минимальное отклонение, чтобы избежать деления на ноль при идеальном совпадении
    deviations.dwell[key] = Math.sqrt(variance) || 5; 
  });

  allFlightKeys.forEach(key => {
    const mean = means.flight[key];
    const variance = samples.reduce((acc, s) => acc + Math.pow((s.flightTimes[key] || mean) - mean, 2), 0) / count;
    deviations.flight[key] = Math.sqrt(variance) || 5;
  });

  // 4. Установка порога. 
  // В реальной системе это сложный процесс (EER - Equal Error Rate).
  // Здесь берем эмпирическое правило: среднее отклонение в обучающей выборке * коэффициент безопасности.
  // Упрощенно: фиксированный порог для демонстрации, зависящий от длины фразы.
  const threshold = 1.5; // Коэффициент строгости

  return {
    phrase,
    sampleCount: count,
    means,
    deviations,
    threshold,
  };
};

// Верификация (Сравнение текущего ввода с шаблоном)
// Используем Manhattan Scaled Distance (одна из самых популярных метрик в статьях по Keystroke Dynamics)
export const verifyUser = (features: KeystrokeFeatures, template: UserTemplate): { score: number, isMatch: boolean } => {
  let totalDistance = 0;
  let featuresCount = 0;

  // Сравнение Dwell Times
  Object.keys(template.means.dwell).forEach(key => {
    const mean = template.means.dwell[key];
    const dev = template.deviations.dwell[key];
    const current = features.dwellTimes[key];

    if (current !== undefined) {
      // Z-score like distance: |x - u| / sigma
      totalDistance += Math.abs(current - mean) / dev;
      featuresCount++;
    } else {
        // Штраф за пропущенную клавишу (или ошибку ввода)
        totalDistance += 3; // Эквивалент 3 сигм
        featuresCount++;
    }
  });

  // Сравнение Flight Times
  Object.keys(template.means.flight).forEach(key => {
    const mean = template.means.flight[key];
    const dev = template.deviations.flight[key];
    const current = features.flightTimes[key];

    if (current !== undefined) {
      totalDistance += Math.abs(current - mean) / dev;
      featuresCount++;
    } else {
       // Штраф за отличие ритма
       totalDistance += 3;
       featuresCount++;
    }
  });

  if (featuresCount === 0) return { score: 100, isMatch: false };

  // Нормализованная оценка (среднее отклонение в сигмах)
  const finalScore = totalDistance / featuresCount;

  // Если среднее отклонение меньше порога (например, в среднем отклоняемся не более чем на 1.5 сигмы), то доступ разрешен
  const isMatch = finalScore < template.threshold;

  return { score: finalScore, isMatch };
};

import { User } from '../types';

const USERS_KEY = 'bioauth_users';

export const StorageService = {
  getUsers: (): User[] => {
    const data = localStorage.getItem(USERS_KEY);
    return data ? JSON.parse(data) : [];
  },

  saveUser: (user: User) => {
    const users = StorageService.getUsers();
    // Update if exists, else add
    const existingIndex = users.findIndex(u => u.username === user.username);
    if (existingIndex >= 0) {
      users[existingIndex] = user;
    } else {
      users.push(user);
    }
    localStorage.setItem(USERS_KEY, JSON.stringify(users));
  },

  findUser: (username: string): User | undefined => {
    const users = StorageService.getUsers();
    return users.find(u => u.username === username);
  },

  clear: () => {
      localStorage.removeItem(USERS_KEY);
  }
};

import React, { useRef, useState } from 'react';
import { RawKeyEvent } from '../types';
import { Eye, EyeOff, Keyboard } from 'lucide-react';

interface Props {
  value: string;
  onChange: (val: string) => void;
  onComplete: (events: RawKeyEvent[]) => void;
  placeholder?: string;
  disabled?: boolean;
  isPassword?: boolean;
}

export const KeystrokeInput: React.FC<Props> = ({ 
  value, 
  onChange, 
  onComplete, 
  placeholder = "Type here...", 
  disabled = false,
  isPassword = true
}) => {
  const [showPassword, setShowPassword] = useState(!isPassword);
  const eventsRef = useRef<RawKeyEvent[]>([]);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    // Игнорируем системные клавиши, которые не влияют на ритм текста напрямую (Shift, Tab и т.д. можно учитывать, но для простоты опустим)
    if (e.key === 'Tab' || e.key === 'Shift') return;

    // Сброс при Backspace для чистоты эксперимента (в ВКР можно обрабатывать и исправления, но это сложнее)
    if (e.key === 'Backspace') {
      eventsRef.current = [];
      onChange('');
      return;
    }

    if (e.key === 'Enter') {
      onComplete(eventsRef.current);
      // Очистка событий после отправки не делается здесь, чтобы родитель мог их забрать
      return;
    }

    eventsRef.current.push({
      code: e.code,
      key: e.key,
      type: 'keydown',
      timestamp: performance.now()
    });
  };

  const handleKeyUp = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Tab' || e.key === 'Shift' || e.key === 'Enter' || e.key === 'Backspace') return;

    eventsRef.current.push({
      code: e.code,
      key: e.key,
      type: 'keyup',
      timestamp: performance.now()
    });
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onChange(e.target.value);
    if (e.target.value === '') {
        eventsRef.current = [];
    }
  };

  return (
    <div className="relative w-full">
      <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-gray-400">
        <Keyboard size={18} />
      </div>
      <input
        type={showPassword ? "text" : "password"}
        className={`block w-full pl-10 pr-10 py-3 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all outline-none ${
          disabled ? 'bg-gray-100 text-gray-400' : 'bg-white text-gray-900 border-gray-300'
        }`}
        placeholder={placeholder}
        value={value}
        onKeyDown={handleKeyDown}
        onKeyUp={handleKeyUp}
        onChange={handleChange}
        disabled={disabled}
        autoComplete="off"
      />
      {isPassword && (
        <button
          type="button"
          onClick={() => setShowPassword(!showPassword)}
          className="absolute inset-y-0 right-0 pr-3 flex items-center text-gray-400 hover:text-gray-600 cursor-pointer"
        >
          {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
        </button>
      )}
    </div>
  );
};

import React from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, LineChart, Line } from 'recharts';
import { UserTemplate, KeystrokeFeatures } from '../types';

interface Props {
  template: UserTemplate;
  currentAttempt?: KeystrokeFeatures;
}

export const BiometricVisualizer: React.FC<Props> = ({ template, currentAttempt }) => {
  // Подготовка данных для графика удержания (Dwell)
  const dwellData = Object.keys(template.means.dwell).map(key => ({
    key,
    mean: Math.round(template.means.dwell[key]),
    dev: Math.round(template.deviations.dwell[key]),
    current: currentAttempt ? Math.round(currentAttempt.dwellTimes[key] || 0) : null
  }));

  // Подготовка данных для графика полета (Flight)
  // Берем только первые 10 диграфов для чистоты графика
  const flightData = Object.keys(template.means.flight).slice(0, 10).map(key => ({
    key: key.replace('Key', '').replace('->Key', '→'),
    mean: Math.round(template.means.flight[key]),
    current: currentAttempt ? Math.round(currentAttempt.flightTimes[key] || 0) : null
  }));

  return (
    <div className="space-y-8">
      <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
        <h3 className="text-lg font-semibold text-gray-800 mb-4 flex items-center gap-2">
          <span className="w-2 h-6 bg-blue-500 rounded-full"></span>
          Динамика удержания клавиш (Dwell Time)
        </h3>
        <p className="text-sm text-gray-500 mb-6">
          Сравнение эталонного времени удержания (синий) с текущей попыткой (фиолетовый). 
          Полосы погрешности отсутствуют для упрощения визуализации.
        </p>
        <div className="h-64 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={dwellData} margin={{ top: 5, right: 30, left: 20, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" />
              <XAxis dataKey="key" tick={{fontSize: 12}} />
              <YAxis unit="ms" tick={{fontSize: 12}} />
              <Tooltip 
                contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}
              />
              <Legend />
              <Bar name="Эталон (мс)" dataKey="mean" fill="#3b82f6" radius={[4, 4, 0, 0]} />
              {currentAttempt && (
                <Bar name="Текущий ввод (мс)" dataKey="current" fill="#8b5cf6" radius={[4, 4, 0, 0]} />
              )}
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
        <h3 className="text-lg font-semibold text-gray-800 mb-4 flex items-center gap-2">
           <span className="w-2 h-6 bg-emerald-500 rounded-full"></span>
           Ритм набора (Flight Time / Digraphs)
        </h3>
        <p className="text-sm text-gray-500 mb-6">
          Временные интервалы между нажатиями клавиш. Характеризует "мелодию" набора пользователя.
        </p>
        <div className="h-64 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={flightData} margin={{ top: 5, right: 30, left: 20, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" />
              <XAxis dataKey="key" tick={{fontSize: 10}} interval={0} />
              <YAxis unit="ms" tick={{fontSize: 12}} />
              <Tooltip 
                 contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}
              />
              <Legend />
              <Line type="monotone" name="Эталонный ритм" dataKey="mean" stroke="#10b981" strokeWidth={3} dot={{r: 4}} />
              {currentAttempt && (
                <Line type="monotone" name="Текущий ритм" dataKey="current" stroke="#f59e0b" strokeWidth={3} dot={{r: 4}} />
              )}
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { KeystrokeInput } from './components/KeystrokeInput';
import { BiometricVisualizer } from './components/BiometricVisualizer';
import { RawKeyEvent, User, KeystrokeFeatures, AuthResult } from './types';
import { extractFeatures, createTemplate, verifyUser } from './utils/biometrics';
import { StorageService } from './services/storageService';
import { ShieldCheck, ShieldAlert, UserPlus, LogIn, Activity, Database, Lock } from 'lucide-react';

// Эталонная фраза для ВКР. 
// В реальной системе пользователь может задавать свою, но для унификации эксперимента берем фиксированную.
const TEST_PHRASE = "biometric-auth-2024";

export default function App() {
  const [activeTab, setActiveTab] = useState<'login' | 'register' | 'dashboard'>('login');
  const [username, setUsername] = useState('');
  const [inputPhrase, setInputPhrase] = useState('');

  // Registration State
  const [regSamples, setRegSamples] = useState<KeystrokeFeatures[]>([]);
  const [regStep, setRegStep] = useState(0);
  const REQUIRED_SAMPLES = 5;

  // Verification State
  const [authResult, setAuthResult] = useState<AuthResult | null>(null);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [lastFeatures, setLastFeatures] = useState<KeystrokeFeatures | undefined>(undefined);

  // System State
  const [users, setUsers] = useState<User[]>([]);

  useEffect(() => {
    setUsers(StorageService.getUsers());
  }, [activeTab]);

  const handleRegisterInput = (events: RawKeyEvent[]) => {
    if (inputPhrase !== TEST_PHRASE) {
      alert(`Ошибка: Фраза должна быть строго: "${TEST_PHRASE}"`);
      setInputPhrase('');
      return;
    }

    const features = extractFeatures(events);
    const newSamples = [...regSamples, features];
    setRegSamples(newSamples);
    setRegStep(prev => prev + 1);
    setInputPhrase('');

    if (newSamples.length >= REQUIRED_SAMPLES) {
      // Finish registration
      const template = createTemplate(newSamples, TEST_PHRASE);
      const newUser: User = {
        id: crypto.randomUUID(),
        username,
        template,
        createdAt: Date.now()
      };
      StorageService.saveUser(newUser);
      alert("Профиль пользователя успешно создан и сохранен в БД.");
      setRegSamples([]);
      setRegStep(0);
      setUsername('');
      setActiveTab('login');
    }
  };

  const handleLoginInput = (events: RawKeyEvent[]) => {
    const user = StorageService.findUser(username);
    if (!user || !user.template) {
      setAuthResult({
        success: false,
        score: 0,
        threshold: 0,
        details: "Пользователь не найден",
        timestamp: Date.now()
      });
      return;
    }

    const features = extractFeatures(events);
    setLastFeatures(features);
    const result = verifyUser(features, user.template);

    setAuthResult({
      success: result.isMatch,
      score: result.score,
      threshold: user.template.threshold,
      details: result.isMatch ? "Биометрический профиль подтвержден" : "Аномалия клавиатурного почерка",
      timestamp: Date.now()
    });

    if (result.isMatch) {
      setCurrentUser(user);
    }
  };

  const resetAuth = () => {
    setAuthResult(null);
    setCurrentUser(null);
    setInputPhrase('');
    setLastFeatures(undefined);
  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-800 pb-20">
      {/* Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-50">
        <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
              <Activity size={20} />
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-indigo-600">
              BioAuth <span className="text-xs font-medium text-gray-500 bg-gray-100 px-2 py-0.5 rounded-full border">vkr-prototype</span>
            </h1>
          </div>
          <nav className="flex gap-1 bg-gray-100 p-1 rounded-lg">
            <button
              onClick={() => setActiveTab('login')}
              className={`px-4 py-1.5 text-sm font-medium rounded-md transition-all ${
                activeTab === 'login' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'
              }`}
            >
              Аутентификация
            </button>
            <button
              onClick={() => setActiveTab('register')}
              className={`px-4 py-1.5 text-sm font-medium rounded-md transition-all ${
                activeTab === 'register' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'
              }`}
            >
              Обучение (Enrollment)
            </button>
          </nav>
        </div>
      </header>

      <main className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-10">

        {/* VIEW: LOGIN */}
        {activeTab === 'login' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            <div className="lg:col-span-5 space-y-6">
              <div className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
                <div className="mb-6">
                  <h2 className="text-2xl font-bold mb-2">Вход в систему</h2>
                  <p className="text-gray-500 text-sm">Введите учетные данные. Система проанализирует не только пароль, но и то, <b>как</b> вы его вводите.</p>
                </div>

                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Идентификатор пользователя</label>
                    <input 
                      type="text" 
                      className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                      placeholder="username"
                      value={username}
                      onChange={(e) => setUsername(e.target.value)}
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Кодовая фраза</label>
                    <KeystrokeInput 
                      value={inputPhrase}
                      onChange={setInputPhrase}
                      onComplete={handleLoginInput}
                      placeholder={TEST_PHRASE}
                    />
                    <p className="text-xs text-gray-400 mt-2 text-right">Нажмите Enter для проверки</p>
                  </div>
                </div>

                {authResult && (
                  <div className={`mt-6 p-4 rounded-xl border ${authResult.success ? 'bg-green-50 border-green-200' : 'bg-red-50 border-red-200'}`}>
                    <div className="flex items-start gap-3">
                      {authResult.success ? <ShieldCheck className="text-green-600" /> : <ShieldAlert className="text-red-600" />}
                      <div>
                        <h4 className={`font-bold ${authResult.success ? 'text-green-800' : 'text-red-800'}`}>
                          {authResult.success ? 'Доступ разрешен' : 'В доступе отказано'}
                        </h4>
                        <p className={`text-sm mt-1 ${authResult.success ? 'text-green-700' : 'text-red-700'}`}>
                          {authResult.details}
                        </p>
                        <div className="mt-2 text-xs font-mono opacity-80">
                          Score: {authResult.score.toFixed(4)} (Threshold: {authResult.threshold.toFixed(2)})
                        </div>
                      </div>
                    </div>
                  </div>
                )}

                {authResult && (
                    <button onClick={resetAuth} className="w-full mt-4 py-2 text-sm text-gray-500 hover:text-gray-900 border border-gray-200 rounded-lg hover:bg-gray-50 transition-colors">
                        Сбросить результат
                    </button>
                )}
              </div>

              <div className="bg-blue-50 p-6 rounded-2xl border border-blue-100">
                <h4 className="font-semibold text-blue-900 mb-2 flex items-center gap-2">
                    <Database size={16} /> Пользователи в базе
                </h4>
                {users.length === 0 ? (
                    <p className="text-sm text-blue-700">База пуста. Перейдите на вкладку Обучение.</p>
                ) : (
                    <ul className="space-y-2">
                        {users.map(u => (
                            <li key={u.id} className="text-sm flex justify-between bg-white px-3 py-2 rounded-md shadow-sm border border-blue-100 cursor-pointer hover:bg-blue-50" onClick={() => setUsername(u.username)}>
                                <span className="font-medium">{u.username}</span>
                                <span className="text-gray-400 text-xs">{new Date(u.createdAt).toLocaleDateString()}</span>
                            </li>
                        ))}
                    </ul>
                )}
              </div>
            </div>

            <div className="lg:col-span-7">
              {currentUser && currentUser.template ? (
                 <BiometricVisualizer template={currentUser.template} currentAttempt={lastFeatures} />
              ) : (
                <div className="h-full min-h-[400px] flex flex-col items-center justify-center bg-white rounded-2xl border border-dashed border-gray-300 p-8 text-center text-gray-400">
                    <Activity size={48} className="mb-4 opacity-20" />
                    <p>Введите данные для визуализации биометрического вектора.</p>
                </div>
              )}
            </div>
          </div>
        )}

        {/* VIEW: REGISTER */}
        {activeTab === 'register' && (
          <div className="max-w-2xl mx-auto">
            <div className="bg-white p-8 rounded-2xl shadow-lg border border-gray-100">
              <div className="text-center mb-8">
                <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mx-auto mb-4">
                  <UserPlus size={32} />
                </div>
                <h2 className="text-2xl font-bold">Создание биометрического профиля</h2>
                <p className="text-gray-500 mt-2">
                  Для обучения нейросети (или статистической модели) необходимо собрать несколько образцов вашего почерка.
                </p>
              </div>

              <div className="space-y-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Придумайте Username</label>
                  <input 
                    type="text" 
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                    placeholder="ivan_petrov"
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                    disabled={regStep > 0}
                  />
                </div>

                <div className="bg-gray-50 p-6 rounded-xl border border-gray-200">
                  <div className="flex justify-between text-sm font-medium text-gray-500 mb-2">
                    <span>Прогресс обучения</span>
                    <span>{regStep} / {REQUIRED_SAMPLES}</span>
                  </div>
                  <div className="w-full bg-gray-200 rounded-full h-2 mb-6">
                    <div 
                      className="bg-blue-600 h-2 rounded-full transition-all duration-500" 
                      style={{ width: `${(regStep / REQUIRED_SAMPLES) * 100}%` }}
                    ></div>
                  </div>

                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Введите фразу: <span className="font-mono bg-white px-2 py-0.5 rounded border text-blue-600">{TEST_PHRASE}</span>
                  </label>
                  <KeystrokeInput 
                    value={inputPhrase}
                    onChange={setInputPhrase}
                    onComplete={handleRegisterInput}
                    placeholder={TEST_PHRASE}
                    isPassword={false}
                    disabled={!username}
                  />
                  <p className="text-xs text-gray-400 mt-2 text-center">Нажимайте Enter после каждого ввода</p>
                </div>

                <div className="text-xs text-gray-400 leading-relaxed bg-yellow-50 p-4 rounded-lg border border-yellow-100 text-yellow-800">
                    <strong>Внимание:</strong> Старайтесь вводить фразу в своем естественном темпе. Не пытайтесь печатать слишком быстро или искусственно медленно. Система анализирует микропаузы.
                </div>
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

