import { KeystrokeFeatures, RegistrationResponse, UserSummary, VerificationResponse } from '../types';

const API_URL = 'http://localhost:8000'; // Адрес вашего Python сервера

export const ApiService = {
  // Проверка доступности сервера
  healthCheck: async (): Promise<boolean> => {
    try {
      const res = await fetch(`${API_URL}/health`);
      return res.ok;
    } catch (e) {
      return false;
    }
  },

  // Получение списка пользователей
  getUsers: async (): Promise<UserSummary[]> => {
    const res = await fetch(`${API_URL}/users`);
    if (!res.ok) throw new Error('Failed to fetch users');
    return res.json();
  },

  // Регистрация (отправка серии образцов для создания шаблона)
  registerUser: async (username: string, samples: KeystrokeFeatures[]): Promise<RegistrationResponse> => {
    const res = await fetch(`${API_URL}/register`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username, samples }),
    });
    if (!res.ok) {
      const err = await res.json();
      throw new Error(err.detail || 'Registration failed');
    }
    return res.json();
  },

  // Верификация (отправка одного образца для проверки)
  verifyUser: async (username: string, sample: KeystrokeFeatures): Promise<VerificationResponse> => {
    const res = await fetch(`${API_URL}/verify`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username, sample }),
    });
    if (!res.ok) {
        const err = await res.json();
        throw new Error(err.detail || 'Verification failed');
    }
    return res.json();
  },

  // Получение шаблона для визуализации (опционально)
  getTemplate: async (username: string) => {
      const res = await fetch(`${API_URL}/users/${username}/template`);
      if (!res.ok) return null;
      return res.json();
  }
};

import React, { useState, useEffect } from 'react';
import { KeystrokeInput } from './components/KeystrokeInput';
import { BiometricVisualizer } from './components/BiometricVisualizer';
import { RawKeyEvent, KeystrokeFeatures, VerificationResponse, UserSummary, UserTemplate } from './types';
import { extractFeatures } from './utils/biometrics';
import { ApiService } from './services/apiService';
import { ShieldCheck, ShieldAlert, UserPlus, Activity, Database, ServerCrash, RefreshCw } from 'lucide-react';

const TEST_PHRASE = "biometric-auth-2024";

export default function App() {
  const [activeTab, setActiveTab] = useState<'login' | 'register'>('login');
  const [username, setUsername] = useState('');
  const [inputPhrase, setInputPhrase] = useState('');

  // Server State
  const [serverOnline, setServerOnline] = useState<boolean>(false);
  const [loading, setLoading] = useState<boolean>(false);
  const [users, setUsers] = useState<UserSummary[]>([]);

  // Registration State
  const [regSamples, setRegSamples] = useState<KeystrokeFeatures[]>([]);
  const [regStep, setRegStep] = useState(0);
  const REQUIRED_SAMPLES = 5;

  // Verification/Vis State
  const [authResult, setAuthResult] = useState<VerificationResponse | null>(null);
  const [currentTemplate, setCurrentTemplate] = useState<UserTemplate | any>(null); // Тип any т.к. структура с бэка может чуть отличаться
  const [lastFeatures, setLastFeatures] = useState<KeystrokeFeatures | undefined>(undefined);

  const checkServer = async () => {
    const isOnline = await ApiService.healthCheck();
    setServerOnline(isOnline);
    if (isOnline) fetchUsers();
  };

  const fetchUsers = async () => {
    try {
      const list = await ApiService.getUsers();
      setUsers(list);
    } catch (e) {
      console.error(e);
    }
  };

  useEffect(() => {
    checkServer();
    const interval = setInterval(checkServer, 5000); // Poll server status
    return () => clearInterval(interval);
  }, []);

  // --- Handlers ---

  const handleRegisterInput = async (events: RawKeyEvent[]) => {
    if (inputPhrase !== TEST_PHRASE) {
      alert(`Ошибка: Фраза должна быть строго: "${TEST_PHRASE}"`);
      setInputPhrase('');
      return;
    }

    const features = extractFeatures(events);
    const newSamples = [...regSamples, features];
    setRegSamples(newSamples);
    setRegStep(prev => prev + 1);
    setInputPhrase('');

    if (newSamples.length >= REQUIRED_SAMPLES) {
      setLoading(true);
      try {
        await ApiService.registerUser(username, newSamples);
        alert("Профиль успешно создан на сервере (PostgreSQL)!");
        setRegSamples([]);
        setRegStep(0);
        setUsername('');
        setActiveTab('login');
        fetchUsers();
      } catch (e: any) {
        alert("Ошибка регистрации: " + e.message);
        setRegSamples([]); // Сброс при ошибке
        setRegStep(0);
      } finally {
        setLoading(false);
      }
    }
  };

  const handleLoginInput = async (events: RawKeyEvent[]) => {
    if (!username) {
        alert("Введите имя пользователя");
        return;
    }
    setLoading(true);
    setAuthResult(null);

    const features = extractFeatures(events);
    setLastFeatures(features);

    try {
      // 1. Верификация на сервере
      const result = await ApiService.verifyUser(username, features);
      setAuthResult(result);

      // 2. Подгрузка шаблона для визуализации (только если успешно или для анализа)
      const tpl = await ApiService.getTemplate(username);
      setCurrentTemplate(tpl);

    } catch (e: any) {
      setAuthResult({
          success: false,
          score: 0,
          threshold: 0,
          details: "Ошибка сервера: " + e.message,
          username: username
      });
    } finally {
      setLoading(false);
    }
  };

  const resetAuth = () => {
    setAuthResult(null);
    setInputPhrase('');
    setLastFeatures(undefined);
    setCurrentTemplate(null);
  };

  if (!serverOnline) {
      return (
          <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50 text-gray-600 p-4">
              <ServerCrash size={64} className="text-red-400 mb-4" />
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Сервер недоступен</h1>
              <p className="text-center max-w-md mb-6">
                  Для работы системы необходимо запустить Python-сервер (FastAPI) с базой данных PostgreSQL.
              </p>
              <div className="bg-white p-4 rounded-lg border border-gray-200 shadow-sm text-sm font-mono text-left w-full max-w-lg">
                  <p className="mb-2 text-gray-500">1. Установите зависимости:</p>
                  <p className="bg-gray-100 p-2 rounded mb-4">pip install fastapi uvicorn psycopg2-binary sqlalchemy numpy scipy pydantic</p>
                  <p className="mb-2 text-gray-500">2. Запустите сервер:</p>
                  <p className="bg-gray-100 p-2 rounded">uvicorn main:app --reload</p>
              </div>
              <button onClick={checkServer} className="mt-8 flex items-center gap-2 px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition">
                  <RefreshCw size={18} /> Проверить соединение
              </button>
          </div>
      );
  }

  return (
    <div className="min-h-screen bg-gray-50 text-gray-800 pb-20">
      {/* Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-50">
        <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
              <Activity size={20} />
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-indigo-600">
              BioAuth <span className="text-xs font-medium text-gray-500 bg-gray-100 px-2 py-0.5 rounded-full border">Python+PG</span>
            </h1>
          </div>
          <nav className="flex gap-1 bg-gray-100 p-1 rounded-lg">
            <button
              onClick={() => setActiveTab('login')}
              className={`px-4 py-1.5 text-sm font-medium rounded-md transition-all ${
                activeTab === 'login' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'
              }`}
            >
              Аутентификация
            </button>
            <button
              onClick={() => setActiveTab('register')}
              className={`px-4 py-1.5 text-sm font-medium rounded-md transition-all ${
                activeTab === 'register' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'
              }`}
            >
              Обучение
            </button>
          </nav>
        </div>
      </header>

      <main className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-10">

        {/* VIEW: LOGIN */}
        {activeTab === 'login' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            <div className="lg:col-span-5 space-y-6">
              <div className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
                <h2 className="text-2xl font-bold mb-6">Вход в систему</h2>

                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Пользователь</label>
                    <input 
                      type="text" 
                      className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                      placeholder="username"
                      value={username}
                      onChange={(e) => setUsername(e.target.value)}
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Контрольная фраза</label>
                    <KeystrokeInput 
                      value={inputPhrase}
                      onChange={setInputPhrase}
                      onComplete={handleLoginInput}
                      placeholder={TEST_PHRASE}
                      disabled={loading}
                    />
                  </div>
                </div>

                {loading && <div className="mt-4 text-center text-blue-600">Обработка данных на сервере...</div>}

                {authResult && !loading && (
                  <div className={`mt-6 p-4 rounded-xl border ${authResult.success ? 'bg-green-50 border-green-200' : 'bg-red-50 border-red-200'}`}>
                    <div className="flex items-start gap-3">
                      {authResult.success ? <ShieldCheck className="text-green-600" /> : <ShieldAlert className="text-red-600" />}
                      <div>
                        <h4 className={`font-bold ${authResult.success ? 'text-green-800' : 'text-red-800'}`}>
                          {authResult.success ? 'Доступ разрешен' : 'В доступе отказано'}
                        </h4>
                        <p className={`text-sm mt-1 ${authResult.success ? 'text-green-700' : 'text-red-700'}`}>
                          {authResult.details}
                        </p>
                        <div className="mt-2 text-xs font-mono opacity-80">
                          Score: {authResult.score.toFixed(4)} / Limit: {authResult.threshold.toFixed(2)}
                        </div>
                      </div>
                    </div>
                    <button onClick={resetAuth} className="w-full mt-4 py-2 text-sm text-gray-500 border border-gray-200 rounded hover:bg-white">
                        Очистить
                    </button>
                  </div>
                )}
              </div>

              <div className="bg-blue-50 p-6 rounded-2xl border border-blue-100">
                <h4 className="font-semibold text-blue-900 mb-2 flex items-center gap-2">
                    <Database size={16} /> PostgreSQL Users
                </h4>
                <ul className="space-y-2 max-h-60 overflow-y-auto">
                    {users.map(u => (
                        <li key={u.id} className="text-sm flex justify-between bg-white px-3 py-2 rounded-md shadow-sm border border-blue-100 cursor-pointer hover:bg-blue-50" onClick={() => setUsername(u.username)}>
                            <span className="font-medium">{u.username}</span>
                            <span className="text-gray-400 text-xs">{new Date(u.created_at).toLocaleDateString()}</span>
                        </li>
                    ))}
                </ul>
              </div>
            </div>

            <div className="lg:col-span-7">
               {currentTemplate ? (
                 <BiometricVisualizer template={currentTemplate} currentAttempt={lastFeatures} />
              ) : (
                <div className="h-full min-h-[400px] flex flex-col items-center justify-center bg-white rounded-2xl border border-dashed border-gray-300 p-8 text-center text-gray-400">
                    <Activity size={48} className="mb-4 opacity-20" />
                    <p>Введите данные. Визуализация загрузится с сервера после попытки входа.</p>
                </div>
              )}
            </div>
          </div>
        )}

        {/* VIEW: REGISTER */}
        {activeTab === 'register' && (
          <div className="max-w-2xl mx-auto">
            <div className="bg-white p-8 rounded-2xl shadow-lg border border-gray-100">
              <div className="text-center mb-8">
                <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mx-auto mb-4">
                  <UserPlus size={32} />
                </div>
                <h2 className="text-2xl font-bold">Обучение нейросети</h2>
              </div>

              <div className="space-y-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Username</label>
                  <input 
                    type="text" 
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg outline-none"
                    placeholder="ivan_petrov"
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                    disabled={regStep > 0}
                  />
                </div>

                <div className="bg-gray-50 p-6 rounded-xl border border-gray-200">
                  <div className="flex justify-between text-sm font-medium text-gray-500 mb-2">
                    <span>Сбор образцов</span>
                    <span>{regStep} / {REQUIRED_SAMPLES}</span>
                  </div>
                  <div className="w-full bg-gray-200 rounded-full h-2 mb-6">
                    <div 
                      className="bg-blue-600 h-2 rounded-full transition-all duration-500" 
                      style={{ width: `${(regStep / REQUIRED_SAMPLES) * 100}%` }}
                    ></div>
                  </div>

                  <KeystrokeInput 
                    value={inputPhrase}
                    onChange={setInputPhrase}
                    onComplete={handleRegisterInput}
                    placeholder={TEST_PHRASE}
                    isPassword={false}
                    disabled={!username || loading}
                  />
                  {loading && <p className="text-center text-sm text-blue-600 mt-2">Генерация шаблона и запись в БД...</p>}
                </div>
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

