                  <p className="mb-2 text-gray-500">2. Запустите сервер:</p>
                  <p className="bg-gray-100 p-2 rounded">uvicorn main:app --reload</p>
              </div>
              <button onClick={checkServer} className="mt-8 flex items-center gap-2 px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition">
                  <RefreshCw size={18} /> Проверить соединение
              </button>
          </div>
      );
  }

  return (
    <div className="min-h-screen bg-gray-50 text-gray-800 pb-20">
      {/* Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-50">
        <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white">
              <Sigma size={20} />
