            <div className="lg:col-span-5 space-y-6">
              <div className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
                <h2 className="text-2xl font-bold mb-6">Вход в систему</h2>

                <div className="space-y-4">
